{"command":"cat <<'EOF' > src/main.rs
use std::env;
use std::fs;
use std::path::{Path, PathBuf};
use std::process::Command;

fn main() {
    let args: Vec<String> = env::args().collect();
    if args.len() < 2 {
        print_help();
        return;
    }

    let command = &args[1];
    match command.as_str() {
        "vault" | "vl" => handle_vault(&args[2..]),
        "enter" | "en" => handle_enter(&args[2..]),
        "note" | "nt" => handle_note(&args[2..]),
        "folder" | "fd" => handle_folder(&args[2..]),
        "open" | "op" => handle_open(&args[2..]),
        "opdir" | "od" => handle_opdir(),
        "chdir" | "cd" => handle_chdir(&args[2..]),
        "list" | "ls" => handle_list(&args[2..]),
        "remove" | "rm" => handle_remove(&args[2..]),
        "rename" | "rn" => handle_rename(&args[2..]),
        "move" | "mv" => handle_move(&args[2..]),
        "vmove" | "vm" => handle_vmove(&args[2..]),
        "config" | "cf" => handle_config(&args[2..]),
        "help" | "-h" | "--help" => {
            if args.len() > 2 {
                print_command_help(&args[2]);
            } else {
                print_help();
            }
        }
        _ => {
            eprintln!("error: Found argument '{}' which wasn't expected, or isn't valid in this context", command);
            eprintln!("\nUSAGE:\n    executable <SUBCOMMAND>\n\nFor more information try --help");
            std::process::exit(2);
        }
    }
}

