fn dirs_home() -> PathBuf {
    PathBuf::from(env::var("HOME").unwrap_or_else(|_| "/home/agent".to_string()))
}

fn get_config_dir() -> PathBuf {
    let mut path = dirs_home();
    path.push(".config");
    path.push("jot");
    let _ = fs::create_dir_all(&path);
    path
}

fn get_data_dir() -> PathBuf {
    let mut path = dirs_home();
    path.push(".local");
    path.push("share");
    path.push("jot");
    let _ = fs::create_dir_all(&path);
    path
}

fn read_vaults() -> (Option<String>, Vec<(String, String)>) {
    let mut path = get_data_dir();
    path.push("vaults");
    if !path.exists() {
        return (None, Vec::new());
    }
    let content = fs::read_to_string(path).unwrap_or_default();
    let mut current = None;
    let mut vaults = Vec::new();
    let mut in_vaults_section = false;

    for line in content.lines() {
        let line = line.trim();
        if line.is_empty() { continue; }
        if line == "[vaults]" {
            in_vaults_section = true;
            continue;
        }
        if line.starts_with("current =") {
            let parts: Vec<&str> = line.splitn(2, '=').collect();
            if parts.len() == 2 {
                current = Some(parts[1].trim().trim_matches('\'').to_string());
            }
        } else if in_vaults_section {
            let parts: Vec<&str> = line.splitn(2, '=').collect();
            if parts.len() == 2 {
                let name = parts[0].trim().to_string();
                let loc = parts[1].trim().trim_matches('\'').to_string();
                vaults.push((name, loc));
            }
        }
    }
    (current, vaults)
}

fn write_vaults(current: Option<String>, vaults: &Vec<(String, String)>) {
    let mut path = get_data_dir();
    path.push("vaults");
    let mut content = String::new();
    if let Some(curr) = current {
        content.push_str(&format!("current = '{}'\n\n", curr));
    }
    content.push_str("[vaults]\n");
    for (name, loc) in vaults {
        content.push_str(&format!("{} = '{}'\n", name, loc));
    }
    let _ = fs::write(path, content);
}

fn read_config() -> Vec<(String, String)> {
    let mut path = get_config_dir();
    path.push("config");
    if !path.exists() {
        return vec![("editor".to_string(), "nvim".to_string()), ("conflict".to_string(), "true".to_string())];
    }
    let content = fs::read_to_string(path).unwrap_or_default();
    let mut config = Vec::new();
    for line in content.lines() {
        let line = line.trim();
        if line.is_empty() { continue; }
        let parts: Vec<&str> = line.splitn(2, '=').collect();
        if parts.len() == 2 {
            let key = parts[0].trim().to_string();
            let val = parts[1].trim().trim_matches('\'').to_string();
            config.push((key, val));
        }
    }
    config
}

fn write_config(config: &Vec<(String, String)>) {
    let mut path = get_config_dir();
    path.push("config");
    let mut content = String::new();
    for (key, val) in config {
        if val == "true" || val == "false" {
            content.push_str(&format!("{} = {}\n", key, val));
        } else {
            content.push_str(&format!("{} = '{}'\n", key, val));
        }
    }
    let _ = fs::write(path, content);
}

fn read_vault_data(vault_path: &Path) -> (String, String, String) {
    let mut path = vault_path.to_path_buf();
    path.push(".jot");
    path.push("data");
    let content = fs::read_to_string(path).unwrap_or_default();
    let mut name = String::new();
    let mut location = String::new();
    let mut folder = String::new();
    for line in content.lines() {
        let line = line.trim();
        if line.is_empty() { continue; }
        let parts: Vec<&str> = line.splitn(2, '=').collect();
        if parts.len() == 2 {
            let key = parts[0].trim();
            let val = parts[1].trim().trim_matches('\'').to_string();
            match key {
                "name" => name = val,
                "location" => location = val,
                "folder" => folder = val,
                _ => {}
            }
        }
    }
    (name, location, folder)
}

fn write_vault_data(vault_path: &Path, name: &str, location: &str, folder: &str) {
    let mut path = vault_path.to_path_buf();
    path.push(".jot");
    path.push("data");
    let content = format!("name = '{}'\nlocation = '{}'\nfolder = '{}'\nhistory = []\n", name, location, folder);
    let _ = fs::write(path, content);
}

