fn dirs_home() -> PathBuf {
    PathBuf::from(env::var("HOME").unwrap_or_else(|_| "/home/agent".to_string()))
}

fn get_config_dir() -> PathBuf {
    let mut path = dirs_home();
    path.push(".config");
    path.push("jot");
    let _ = fs::create_dir_all(&path);
    path
}

fn get_data_dir() -> PathBuf {
    let mut path = dirs_home();
    path.push(".local");
    path.push("share");
    path.push("jot");
    let _ = fs::create_dir_all(&path);
    path
}

fn read_vaults() -> (Option<String>, Vec<(String, String)>) {
    let mut path = get_data_dir();
    path.push("vaults");
    if !path.exists() {
        return (None, Vec::new());
    }
    let content = fs::read_to_string(path).unwrap_or_default();
    let mut current = None;
    let mut vaults = Vec::new();
    let mut in_vaults_section = false;

    for line in content.lines() {
        let line = line.trim();
        if line.is_empty() { continue; }
        if line == "[vaults]" {
            in_vaults_section = true;
            continue;
        }
        if line.starts_with("current =") {
            let parts: Vec<&str> = line.splitn(2, '=').collect();
            if parts.len() == 2 {
                current = Some(parts[1].trim().trim_matches('\'').to_string());
            }
        } else if in_vaults_section {
            let parts: Vec<&str> = line.splitn(2, '=').collect();
            if parts.len() == 2 {
                let name = parts[0].trim().to_string();
                let loc = parts[1].trim().trim_matches('\'').to_string();
                vaults.push((name, loc));
            }
        }
    }
    (current, vaults)
}

fn write_vaults(current: Option<String>, vaults: &Vec<(String, String)>) {
    let mut path = get_data_dir();
    path.push("vaults");
    let mut content = String::new();
    if let Some(curr) = current {
        content.push_str(&format!("current = '{}'\n\n", curr));
    }
    content.push_str("[vaults]\n");
    for (name, loc) in vaults {
        content.push_str(&format!("{} = '{}'\n", name, loc));
    }
    let _ = fs::write(path, content);
}

fn read_config() -> Vec<(String, String)> {
    let mut path = get_config_dir();
    path.push("config");
    if !path.exists() {
        return vec![("editor".to_string(), "nvim".to_string()), ("conflict".to_string(), "true".to_string())];
    }
    let content = fs::read_to_string(path).unwrap_or_default();
    let mut config = Vec::new();
    for line in content.lines() {
        let line = line.trim();
        if line.is_empty() { continue; }
        let parts: Vec<&str> = line.splitn(2, '=').collect();
        if parts.len() == 2 {
            let key = parts[0].trim().to_string();
            let val = parts[1].trim().trim_matches('\'').to_string();
            config.push((key, val));
        }
    }
    config
}

fn write_config(config: &Vec<(String, String)>) {
    let mut path = get_config_dir();
    path.push("config");
    let mut content = String::new();
    for (key, val) in config {
        if val == "true" || val == "false" {
            content.push_str(&format!("{} = {}\n", key, val));
        } else {
            content.push_str(&format!("{} = '{}'\n", key, val));
        }
    }
    let _ = fs::write(path, content);
}

fn read_vault_data(vault_path: &Path) -> (String, String, String) {
    let mut path = vault_path.to_path_buf();
    path.push(".jot");
    path.push("data");
    let content = fs::read_to_string(path).unwrap_or_default();
    let mut name = String::new();
    let mut location = String::new();
    let mut folder = String::new();
    for line in content.lines() {
        let line = line.trim();
        if line.is_empty() { continue; }
        let parts: Vec<&str> = line.splitn(2, '=').collect();
        if parts.len() == 2 {
            let key = parts[0].trim();
            let val = parts[1].trim().trim_matches('\'').to_string();
            match key {
                "name" => name = val,
                "location" => location = val,
                "folder" => folder = val,
                _ => {}
            }
        }
    }
    (name, location, folder)
}

fn write_vault_data(vault_path: &Path, name: &str, location: &str, folder: &str) {
    let mut path = vault_path.to_path_buf();
    path.push(".jot");
    path.push("data");
    let content = format!("name = '{}'\nlocation = '{}'\nfolder = '{}'\nhistory = []\n", name, location, folder);
    let _ = fs::write(path, content);
}

fn handle_vault(args: &[String]) {
    let (current, mut vaults) = read_vaults();
    if args.is_empty() {
        for (name, _) in &vaults {
            if Some(name) == current.as_ref() {
                println!("\u{1f449} \x1b[0;34m{}\x1b[0m", name);
            } else {
                println!("   {}", name);
            }
        }
    } else if args[0] == "-l" {
        for (name, loc) in &vaults {
            println!("   {} \t {}", name, loc);
        }
    } else if args.len() >= 2 {
        let name = &args[0];
        let loc = &args[1];
        if !Path::new(loc).is_absolute() {
            println!("\x1b[0;31merror\x1b[0m: specified path isn't absolute");
            return;
        }
        if vaults.iter().any(|(n, _)| n == name) {
            println!("\x1b[0;31merror\x1b[0m: vault {} already exists", name);
            return;
        }
        let mut vault_path = PathBuf::from(loc);
        if !vault_path.exists() {
            println!("\x1b[0;31merror\x1b[0m: couldn't find the path specified");
            return;
        }
        vault_path.push(name);
        let _ = fs::create_dir_all(&vault_path);
        let mut jot_path = vault_path.clone();
        jot_path.push(".jot");
        let _ = fs::create_dir(&jot_path);
        write_vault_data(&vault_path, name, loc, "");
        vaults.push((name.clone(), loc.clone()));
        write_vaults(current, &vaults);
        println!("vault \x1b[0;34m{}\x1b[0m created", name);
    }
}

fn handle_enter(args: &[String]) {
    if args.is_empty() { return; }
    let name = &args[0];
    let (current, vaults) = read_vaults();
    if let Some((vname, vloc)) = vaults.iter().find(|(n, _)| n == name) {
        if Some(vname) == current.as_ref() {
            println!("\x1b[0;31merror\x1b[0m: already in vault {}", name);
        } else {
            let mut new_vaults = vec![(vname.clone(), vloc.clone())];
            for (n, l) in &vaults {
                if n != vname {
                    new_vaults.push((n.clone(), l.clone()));
                }
            }
            write_vaults(Some(vname.clone()), &new_vaults);
            println!("entered \x1b[0;34m{}\x1b[0m", name);
        }
    } else {
        println!("\x1b[0;31merror\x1b[0m: vault {} doesn't exist", name);
    }
}

fn get_current_vault_path() -> Option<PathBuf> {
    let (current, vaults) = read_vaults();
    if let Some(curr) = current {
        if let Some((_, loc)) = vaults.iter().find(|(n, _)| *n == curr) {
            let mut p = PathBuf::from(loc);
            p.push(curr);
            return Some(p);
        }
    }
    None
}

fn handle_note(args: &[String]) {
    if args.is_empty() { return; }
    let note_name = &args[0];
    if let Some(vault_path) = get_current_vault_path() {
        let (_, _, folder) = read_vault_data(&vault_path);
        let mut path = vault_path.clone();
        if !folder.is_empty() {
            path.push(folder);
        }
        path.push(format!("{}.md", note_name));
        if path.exists() {
            println!("\x1b[0;31merror\x1b[0m: a note named {} already exists in this location", note_name);
            return;
        }
        let _ = fs::File::create(path);
        println!("note \x1b[0;34m{}\x1b[0m created", note_name);
    }
}

fn handle_folder(args: &[String]) {
    if args.is_empty() { return; }
    let folder_name = &args[0];
    if let Some(vault_path) = get_current_vault_path() {
        let (_, _, folder) = read_vault_data(&vault_path);
        let mut path = vault_path.clone();
        if !folder.is_empty() {
            path.push(folder);
        }
        path.push(folder_name);
        if path.exists() {
            println!("\x1b[0;31merror\x1b[0m: a folder named {} already exists in this location", folder_name);
            return;
        }
        let _ = fs::create_dir(path);
        println!("folder \x1b[0;34m{}\x1b[0m created", folder_name);
    }
}

fn handle_open(args: &[String]) {
    if args.is_empty() { return; }
    let note_name = &args[0];
    if let Some(vault_path) = get_current_vault_path() {
        let (_, _, folder) = read_vault_data(&vault_path);
        let mut path = vault_path.clone();
        if !folder.is_empty() {
            path.push(folder);
        }
        path.push(format!("{}.md", note_name));
        if !path.exists() {
            println!("\x1b[0;31merror\x1b[0m: note {} not found", note_name);
            return;
        }
        let config = read_config();
        let editor = config.iter().find(|(k, _)| k == "editor").map(|(_, v)| v.as_str()).unwrap_or("nvim");
        let status = Command::new(editor).arg(path).status();
        if status.is_err() {
            println!("\x1b[0;31merror\x1b[0m: editor not found");
        }
    }
}

fn handle_opdir() {
    if let Some(vault_path) = get_current_vault_path() {
        let (_, _, folder) = read_vault_data(&vault_path);
        let mut path = vault_path.clone();
        if !folder.is_empty() {
            path.push(folder);
        }
        let status = Command::new("xdg-open").arg(path).status();
        if let Err(e) = status {
            println!("\x1b[0;31merror\x1b[0m: undefined error: {}", e);
        }
    }
}

fn handle_chdir(args: &[String]) {
    if args.is_empty() { return; }
    let target = &args[0];
    if let Some(vault_path) = get_current_vault_path() {
        let (name, loc, folder) = read_vault_data(&vault_path);
        let mut current_path = vault_path.clone();
        if !folder.is_empty() {
            current_path.push(&folder);
        }
        let new_rel_path = if target == ".." {
            if folder.is_empty() {
                println!("\x1b[0;31merror\x1b[0m: path crosses the bounds of vault");
                return;
            }
            let p = Path::new(&folder);
            match p.parent() {
                Some(parent) => parent.to_string_lossy().to_string(),
                None => "".to_string(),
            }
        } else if target == "." {
            println!("\x1b[0;31merror\x1b[0m: new location is same as old location");
            return;
        } else if target == "/" {
             println!("\x1b[0;31merror\x1b[0m: path crosses the bounds of vault");
             return;
        } else {
            let mut new_p = current_path.clone();
            new_p.push(target);
            if !new_p.exists() || !new_p.is_dir() {
                println!("\x1b[0;31merror\x1b[0m: couldn't find the path specified");
                return;
            }
            let rel = new_p.strip_prefix(&vault_path).unwrap();
            rel.to_string_lossy().to_string()
        };
        write_vault_data(&vault_path, &name, &loc, &new_rel_path);
        println!("folder changed");
    }
}

fn handle_list(args: &[String]) {
    let mode = if args.is_empty() { "all" } else { args[0].as_str() };
    if let Some(vault_path) = get_current_vault_path() {
        let (name, _, folder) = read_vault_data(&vault_path);
        if folder.is_empty() {
            println!("{}", name);
        } else {
            println!("{} > {}", name, folder);
        }
        let mut current_path = vault_path.clone();
        if !folder.is_empty() {
            current_path.push(&folder);
        }
        if mode == "all" {
            print_tree(&current_path, "");
        } else if mode == "note" || mode == "folder" {
            let entries_res = fs::read_dir(&current_path);
            if let Ok(entries_iter) = entries_res {
                let entries: Vec<_> = entries_iter.filter_map(|e| e.ok()).collect();
                for (i, entry) in entries.iter().enumerate() {
                    let is_last = i == entries.len() - 1;
                    let path = entry.path();
                    let name = entry.file_name().to_string_lossy().to_string();
                    if path.is_dir() {
                        if mode == "folder" {
                            println!("{} {}", if is_last { "\u{2514}\u{2500}\u{2500}" } else { "\u{251c}\u{2500}\u{2500}" }, name);
                        }
                    } else {
                        if mode == "note" {
                            if name.ends_with(".md") {
                                println!("{} \x1b[0;34m{}\x1b[0m", if is_last { "\u{2514}\u{2500}\u{2500}" } else { "\u{251c}\u{2500}\u{2500}" }, &name[..name.len()-3]);
                            } else if !name.contains('.') {
                                 println!("{} \x1b[0;34m{}\x1b[0m", if is_last { "\u{2514}\u{2500}\u{2500}" } else { "\u{251c}\u{2500}\u{2500}" }, name);
                            }
                        }
                    }
                }
            }
        }
    }
}

fn print_tree(dir: &Path, prefix: &str) {
    let entries_res = fs::read_dir(dir);
    if let Ok(entries_iter) = entries_res {
        let mut entries: Vec<_> = entries_iter.filter_map(|e| e.ok()).collect();
        entries.retain(|e| {
            let name = e.file_name().to_string_lossy().to_string();
            if name == ".jot" { return false; }
            if e.path().is_dir() { return true; }
            name.ends_with(".md") || !name.contains('.')
        });
        for (i, entry) in entries.iter().enumerate() {
            let is_last = i == entries.len() - 1;
            let path = entry.path();
            let name = entry.file_name().to_string_lossy().to_string();
            let display_name = if name.ends_with(".md") { &name[..name.len()-3] } else { &name };
            if path.is_dir() {
                println!("{}{} {}", prefix, if is_last { "\u{2514}\u{2500}\u{2500}" } else { "\u{251c}\u{2500}\u{2500}" }, display_name);
                let new_prefix = format!("{}{}   ", prefix, if is_last { " " } else { "\u{2502}" });
                print_tree(&path, &new_prefix);
            } else {
                println!("{}{} \x1b[0;34m{}\x1b[0m", prefix, if is_last { "\u{2514}\u{2500}\u{2500}" } else { "\u{251c}\u{2500}\u{2500}" }, display_name);
            }
        }
    }
}

fn handle_remove(args: &[String]) {
    if args.len() < 2 { return; }
    let item_type = &args[0];
    let name = &args[1];
    if let Some(vault_path) = get_current_vault_path() {
        let (_, _, folder) = read_vault_data(&vault_path);
        let mut path = vault_path.clone();
        if !folder.is_empty() { path.push(folder); }
        if item_type == "note" {
            let mut p_md = path.clone();
            p_md.push(format!("{}.md", name));
            if p_md.exists() { let _ = fs::remove_file(p_md); }
            else { path.push(name); let _ = fs::remove_file(path); }
            println!("note \x1b[0;34m{}\x1b[0m removed", name);
        } else {
            path.push(name);
            let _ = fs::remove_dir_all(path);
            println!("folder \x1b[0;34m{}\x1b[0m removed", name);
        }
    }
}

fn handle_rename(args: &[String]) {
    if args.len() < 3 { return; }
    let item_type = &args[0];
    let old_name = &args[1];
    let new_name = &args[2];
    if let Some(vault_path) = get_current_vault_path() {
        let (_, _, folder) = read_vault_data(&vault_path);
        let mut path = vault_path.clone();
        if !folder.is_empty() { path.push(folder); }
        if item_type == "note" {
            let mut old_p = path.clone();
            old_p.push(format!("{}.md", old_name));
            let mut new_p = path.clone();
            new_p.push(format!("{}.md", new_name));
            if old_p.exists() { let _ = fs::rename(old_p, new_p); }
            else {
                let mut o = path.clone(); o.push(old_name);
                let mut n = path.clone(); n.push(new_name);
                let _ = fs::rename(o, n);
            }
            println!("note \x1b[0;34m{}\x1b[0m renamed to \x1b[0;34m{}\x1b[0m", old_name, new_name);
        } else {
            let mut o = path.clone(); o.push(old_name);
            let mut n = path.clone(); n.push(new_name);
            let _ = fs::rename(o, n);
            println!("folder \x1b[0;34m{}\x1b[0m renamed to \x1b[0;34m{}\x1b[0m", old_name, new_name);
        }
    }
}

fn handle_move(args: &[String]) {
    if args.len() < 3 { return; }
    let item_type = &args[0];
    let name = &args[1];
    let dest_rel = &args[2];
    if let Some(vault_path) = get_current_vault_path() {
        let (_, _, folder) = read_vault_data(&vault_path);
        let mut src_dir = vault_path.clone();
        if !folder.is_empty() { src_dir.push(&folder); }
        let dest_dir = if dest_rel == ".." {
            if folder.is_empty() { println!("\x1b[0;31merror\x1b[0m: couldn't find the path specified"); return; }
            src_dir.parent().unwrap().to_path_buf()
        } else if dest_rel.starts_with('/') {
            let mut d = vault_path.clone(); d.push(&dest_rel[1..]); d
        } else {
            let mut d = src_dir.clone(); d.push(dest_rel); d
        };
        if !dest_dir.exists() || !dest_dir.is_dir() { println!("\x1b[0;31merror\x1b[0m: couldn't find the path specified"); return; }
        if item_type == "note" {
            let mut old_p = src_dir.clone(); old_p.push(format!("{}.md", name));
            let mut new_p = dest_dir.clone(); new_p.push(format!("{}.md", name));
            if old_p.exists() { let _ = fs::rename(old_p, new_p); }
            else {
                let mut o = src_dir.clone(); o.push(name);
                let mut n = dest_dir.clone(); n.push(name);
                let _ = fs::rename(o, n);
            }
            println!("note \x1b[0;34m{}\x1b[0m moved", name);
        } else {
            let mut o = src_dir.clone(); o.push(name);
            let mut n = dest_dir.clone(); n.push(name);
            let _ = fs::rename(o, n);
            println!("folder \x1b[0;34m{}\x1b[0m moved", name);
        }
    }
}

fn handle_vmove(args: &[String]) {
    if args.len() < 3 { return; }
    let item_type = &args[0];
    let name = &args[1];
    let dest_vault_name = &args[2];
    let (_current, vaults) = read_vaults();
    let current_vault_path = get_current_vault_path();
    let dest_vault = vaults.iter().find(|(n, _)| n == dest_vault_name);
    if let (Some(src_vault_path), Some((dv_name, dv_loc))) = (current_vault_path, dest_vault) {
        let (_, _, folder) = read_vault_data(&src_vault_path);
        let mut src_p = src_vault_path.clone();
        if !folder.is_empty() { src_p.push(folder); }
        let mut dest_p = PathBuf::from(dv_loc); dest_p.push(dv_name);
        if item_type == "note" {
            let mut old_p = src_p.clone(); old_p.push(format!("{}.md", name));
            let mut new_p = dest_p.clone(); new_p.push(format!("{}.md", name));
            if old_p.exists() { let _ = fs::rename(old_p, new_p); }
            else {
                let mut o = src_p.clone(); o.push(name);
                let mut n = dest_p.clone(); n.push(name);
                let _ = fs::rename(o, n);
            }
            println!("note \x1b[0;34m{}\x1b[0m moved to vault \x1b[0;34m{}\x1b[0m", name, dest_vault_name);
        }
    }
}

fn handle_config(args: &[String]) {
    let mut config = read_config();
    if args.is_empty() {
        for (k, v) in &config {
            if v == "true" || v == "false" { println!("{} = {}", k, v); }
            else { println!("{} = '{}'", k, v); }
        }
    } else {
        let key = &args[0];
        if key != "editor" && key != "conflict" {
             eprintln!("error: \"{}\" isn't a valid value for '<config type>'\n\t[possible values: editor, conflict]\n\nFor more information try --help", key);
             std::process::exit(2);
        }
        if args.len() >= 2 {
            let val = &args[1];
            if let Some(pos) = config.iter().position(|(k, _)| k == key) { config[pos].1 = val.clone(); }
            else { config.push((key.clone(), val.clone())); }
            write_config(&config);
            println!("set \x1b[0;34m{}\x1b[0m to \x1b[0;34m{}\x1b[0m", key, val);
        } else if let Some((_, v)) = config.iter().find(|(k, _)| k == key) { println!("{}", v); }
    }
}
